lemma cyclotomic_pair_right {ζ : R}
    (hζ : ζ ^ 4 + ζ ^ 3 + ζ ^ 2 + ζ + 1 = 0) :
    2 * ((ζ ^ 2 - 1) * (ζ ^ 3 - 1)) = 5 + cyclotomicSqrtFive ζ

